 39→//**************************************************************************
 40→//  TYPE DEFINITIONS
 41→//**************************************************************************
 42→
 43→// ======================> tmp94c241_device
 44→
 45→class tmp94c241_device : public tlcs900h_device
 46→{
 47→	friend class tmp94c241_serial_device;
 48→
 49→	static constexpr uint8_t PORT_0 = 0; // 8 bit I/O. Shared with d0-d7
 50→	static constexpr uint8_t PORT_1 = 1; // 8 bit I/O. Shared with d8-d15
 51→	static constexpr uint8_t PORT_2 = 2; // 8 bit I/O. Shared with d16-d23
 52→	static constexpr uint8_t PORT_3 = 3; // 8 bit I/O. Shared with d24-d31
 53→	static constexpr uint8_t PORT_4 = 4; // 8 bit I/O. Shared with a0-a7
 54→	static constexpr uint8_t PORT_5 = 5; // 8 bit I/O. Shared with a8-a15
 55→	static constexpr uint8_t PORT_6 = 6; // 8 bit I/O. Shared with a16-a23
 56→	static constexpr uint8_t PORT_7 = 7; // 8 bit I/O. Shared with external memory & bus signals
 57→	static constexpr uint8_t PORT_8 = 8; // 7 bit I/O. Shared with chip-select signals
 58→	static constexpr uint8_t PORT_A = 9; // 5 bit I/O. Shared with external DRAM (channel 0)
