466→		m_cpr_leds[35] = BIT(data, 2);  // D135 - PART SELECT: RIGHT 1
467→		m_cpr_leds[36] = BIT(data, 3);  // D136 - ENTERTAINER
468→		m_cpr_leds[37] = BIT(data, 4);  // D137 - CONDUCTOR: LEFT
469→		m_cpr_leds[38] = BIT(data, 5);  // D138 - CONDUCTOR: RIGHT 2
470→		m_cpr_leds[39] = BIT(data, 6);  // D139 - CONDUCTOR: RIGHT 1
471→		m_cpr_leds[40] = BIT(data, 7);  // D140 - TECHNI CHORD
472→		break;
473→
474→	case 0x08:
475→		m_cpr_leds[49] = BIT(data, 0);  // D149 - MENU: SOUND
476→		m_cpr_leds[50] = BIT(data, 1);  // D150 - MENU: CONTROL
477→		m_cpr_leds[51] = BIT(data, 2);  // D151 - MENU: MIDI
478→		m_cpr_leds[52] = BIT(data, 3);  // D152 - MENU: DISK
479→		break;
480→
481→	case 0x0a:
482→		m_cpr_leds[57] = BIT(data, 0);  // D157 - MEMORY A
483→		m_cpr_leds[58] = BIT(data, 1);  // D158 - MEMORY B
484→		break;
485→
486→	case 0x0b:
