525→		m_cpl_leds[18] = BIT(data, 1);  // D118 - R & ROLL & BLUES
526→		m_cpl_leds[19] = BIT(data, 2);  // D119 - POP & BALLAD
527→		m_cpl_leds[20] = BIT(data, 3);  // D120 - FUNK & FUSION
528→		m_cpl_leds[21] = BIT(data, 4);  // D121 - SOUL & MODERN DANCE
529→		m_cpl_leds[22] = BIT(data, 5);  // D122 - BIG BAND & SWING
530→		m_cpl_leds[23] = BIT(data, 6);  // D123 - JAZZ COMBO
531→		m_cpl_leds[24] = BIT(data, 7);  // D124 - MANUAL SEQUENCE PADS: MENU
532→		break;
533→
534→	case 0xc3:
535→		m_cpl_leds[25] = BIT(data, 0);  // D125 - VARIATION & MSA 1
536→		m_cpl_leds[26] = BIT(data, 1);  // D126 - VARIATION & MSA 2
537→		m_cpl_leds[27] = BIT(data, 2);  // D127 - VARIATION & MSA 3
538→		m_cpl_leds[28] = BIT(data, 3);  // D128 - VARIATION & MSA 4
539→		m_cpl_leds[29] = BIT(data, 4);  // D129 - MUSIC STYLE ARRANGER
540→		m_cpl_leds[30] = BIT(data, 5);  // D130 - AUTO PLAY CHORD
541→		break;
542→
543→	case 0xc4:
544→		m_cpl_leds[33] = BIT(data, 0);  // D133 - FILL IN 1
545→		m_cpl_leds[34] = BIT(data, 1);  // D134 - FILL IN 2
546→		m_cpl_leds[35] = BIT(data, 2);  // D135 - INTRO & ENDING 1
547→		m_cpl_leds[36] = BIT(data, 3);  // D136 - INTRO & ENDING 2
548→		m_cpl_leds[37] = BIT(data, 4);  // D137 - SPLIT POINT INDICATOR (LEFT)
549→		m_cpl_leds[38] = BIT(data, 5);  // D138 - SPLIT POINT INDICATOR (CENTER)
550→		m_cpl_leds[39] = BIT(data, 6);  // D139 - SPLIT POINT INDICATOR (RIGHT)
551→		m_cpl_leds[40] = BIT(data, 7);  // D140 - TEMPO/PROGRAM
552→		break;
553→
554→	case 0xc8:
555→		m_cpl_leds[49] = BIT(data, 0);  // D149 - OTHER PARTS/TR
556→		break;
557→	}
558→}
