100→		// m_rxd before we can sample it. Capture the value first.

 88→void tmp94c241_serial_device::sioclk(int state)
 89→{
 90→	if (m_sioclk_state == state)
 91→		return;
 92→
 93→	m_sioclk_state = state;
 94→
 95→	if (state)
 96→	{
 97→		// Rising edge: Sample RXD BEFORE forwarding clock to slave.
 98→		// The slave's rising-edge handler may complete an RX byte and call
 99→		// send_byte(), which pre-outputs bit 0 via m_txd_cb — changing our
100→		// m_rxd before we can sample it. Capture the value first.
101→		uint8_t rxd_sample = m_rxd;
102→
103→		m_sclk_out_cb(state);
104→
105→		logerror("sioclk state=%d rxd=%d m_rx_clock_count=%d m_tx_clock_count=%d\n", m_sioclk_state, rxd_sample, m_rx_clock_count, m_tx_clock_count);
106→
107→		if (m_rx_clock_count){
108→			m_rx_clock_count--;
109→
110→			m_rx_shift_register >>= 1;
111→			m_rx_shift_register |= (rxd_sample << 7);
112→
113→			if (m_rx_clock_count == 0)
114→			{
115→				m_rx_clock_count = 8;
116→				m_rx_buffer = m_rx_shift_register;
117→				logerror("RX byte received: %02X\n", m_rx_buffer);
118→				m_cpu->m_int_reg[(m_channel == 0) ? INTES0 : INTES1] |= 0x08;
119→				m_cpu->m_check_irqs = 1;
120→			}
121→		}
122→	}
123→	else
124→	{
125→		// Falling edge: Forward clock to slave, then output our TXD.
126→		// Order doesn't matter for data correctness here — both sides
127→		// output on falling edges and sample on rising edges.
128→		m_sclk_out_cb(state);
129→
130→		logerror("sioclk state=%d rxd=%d m_rx_clock_count=%d m_tx_clock_count=%d\n", m_sioclk_state, m_rxd, m_rx_clock_count, m_tx_clock_count);
131→
132→		if (m_tx_clock_count){
133→			if (m_tx_skip_first_falling) {
134→				// Skip this falling edge - bit 0 was pre-output in scNbuf_w
135→				// and we need to give the receiver a rising edge to sample it
136→				logerror("skipping first falling edge (bit 0 already on line)\n");
137→				m_tx_skip_first_falling = false;
138→			} else {
139→				// Normal operation: shift out the next bit
140→				m_tx_shift_register >>= 1;
141→				logerror("send bit #%d: %d\n", 8-m_tx_clock_count, m_tx_shift_register & 1);
142→
143→				m_txd_cb(m_tx_shift_register & 1);
144→				if (--m_tx_clock_count == 0) {
145→					logerror("Finished sending byte.\n");
146→					// We finished sending the data:
147→					m_cpu->m_int_reg[(m_channel == 0) ? INTES0 : INTES1] |= 0x80;
148→					m_cpu->m_check_irqs = 1;
149→				}
150→			}
151→		}
152→	}
153→}
