412→void kn5000_cpanel_device::process_led_command(uint8_t row, uint8_t data)
413→{
414→	LOGMASKED(LOG_LEDS, "LED command: row=%02X data=%02X\n", row, data);
415→
416→	switch (row)
417→	{
418→	// Right panel LED rows
419→	case 0x00:
420→		m_cpr_leds[1] = BIT(data, 0);  // D101 - EFFECT: SUSTAIN
421→		m_cpr_leds[2] = BIT(data, 1);  // D102 - EFFECT: DIGITAL EFFECT
422→		m_cpr_leds[3] = BIT(data, 2);  // D103 - EFFECT: DSP EFFECT
423→		m_cpr_leds[4] = BIT(data, 3);  // D104 - EFFECT: DIGITAL REVERB
424→		m_cpr_leds[5] = BIT(data, 4);  // D105 - EFFECT: ACOUSTIC ILLUSION
425→		m_cpr_leds[6] = BIT(data, 5);  // D106 - SEQUENCER: PLAY
426→		m_cpr_leds[7] = BIT(data, 6);  // D107 - SEQUENCER: EASY REC
427→		m_cpr_leds[8] = BIT(data, 7);  // D108 - SEQUENCER: MENU
428→		break;
429→
430→	case 0x01:
431→		m_cpr_leds[9] = BIT(data, 0);   // D109 - PIANO
432→		m_cpr_leds[10] = BIT(data, 1);  // D110 - GUITAR
433→		m_cpr_leds[11] = BIT(data, 2);  // D111 - STRINGS & VOCAL
434→		m_cpr_leds[12] = BIT(data, 3);  // D112 - BRASS
435→		m_cpr_leds[13] = BIT(data, 4);  // D113 - FLUTE
436→		m_cpr_leds[14] = BIT(data, 5);  // D114 - SAX & REED
437→		m_cpr_leds[15] = BIT(data, 6);  // D115 - MALLET & ORCH PERC
438→		m_cpr_leds[16] = BIT(data, 7);  // D116 - WORLD PERC
439→		break;
440→
441→	case 0x02:
442→		m_cpr_leds[17] = BIT(data, 0);  // D117 - ORGAN & ACCORDION
443→		m_cpr_leds[18] = BIT(data, 1);  // D118 - ORCHESTRAL PAD
444→		m_cpr_leds[19] = BIT(data, 2);  // D119 - SYNTH
445→		m_cpr_leds[20] = BIT(data, 3);  // D120 - BASS
446→		m_cpr_leds[21] = BIT(data, 4);  // D121 - DIGITAL DRAWBAR
447→		m_cpr_leds[22] = BIT(data, 5);  // D122 - ACCORDION REGISTER
448→		m_cpr_leds[23] = BIT(data, 6);  // D123 - GM SPECIAL
449→		m_cpr_leds[24] = BIT(data, 7);  // D124 - DRUM KITS
450→		break;
451→
452→	case 0x03:
453→		m_cpr_leds[25] = BIT(data, 0);  // D125 - PANEL MEMORY 1
454→		m_cpr_leds[26] = BIT(data, 1);  // D126 - PANEL MEMORY 2
455→		m_cpr_leds[27] = BIT(data, 2);  // D127 - PANEL MEMORY 3
456→		m_cpr_leds[28] = BIT(data, 3);  // D128 - PANEL MEMORY 4
457→		m_cpr_leds[29] = BIT(data, 4);  // D129 - PANEL MEMORY 5
458→		m_cpr_leds[30] = BIT(data, 5);  // D130 - PANEL MEMORY 6
459→		m_cpr_leds[31] = BIT(data, 6);  // D131 - PANEL MEMORY 7
460→		m_cpr_leds[32] = BIT(data, 7);  // D132 - PANEL MEMORY 8
461→		break;
462→
463→	case 0x04:
464→		m_cpr_leds[33] = BIT(data, 0);  // D133 - PART SELECT: LEFT
465→		m_cpr_leds[34] = BIT(data, 1);  // D134 - PART SELECT: RIGHT 2
466→		m_cpr_leds[35] = BIT(data, 2);  // D135 - PART SELECT: RIGHT 1
467→		m_cpr_leds[36] = BIT(data, 3);  // D136 - ENTERTAINER
468→		m_cpr_leds[37] = BIT(data, 4);  // D137 - CONDUCTOR: LEFT
469→		m_cpr_leds[38] = BIT(data, 5);  // D138 - CONDUCTOR: RIGHT 2
470→		m_cpr_leds[39] = BIT(data, 6);  // D139 - CONDUCTOR: RIGHT 1
471→		m_cpr_leds[40] = BIT(data, 7);  // D140 - TECHNI CHORD
472→		break;
473→
474→	case 0x08:
475→		m_cpr_leds[49] = BIT(data, 0);  // D149 - MENU: SOUND
476→		m_cpr_leds[50] = BIT(data, 1);  // D150 - MENU: CONTROL
477→		m_cpr_leds[51] = BIT(data, 2);  // D151 - MENU: MIDI
478→		m_cpr_leds[52] = BIT(data, 3);  // D152 - MENU: DISK
479→		break;
480→
481→	case 0x0a:
482→		m_cpr_leds[57] = BIT(data, 0);  // D157 - MEMORY A
483→		m_cpr_leds[58] = BIT(data, 1);  // D158 - MEMORY B
484→		break;
485→
486→	case 0x0b:
487→		m_cpr_leds[61] = BIT(data, 0);  // D161 - SYNCHRO & BREAK
488→		m_cpr_leds[62] = BIT(data, 1);  // D162 - R1/R2 OCTAVE MINUS
489→		m_cpr_leds[63] = BIT(data, 2);  // D163 - R1/R2 OCTAVE PLUS
490→		m_cpr_leds[64] = BIT(data, 3);  // D164 - BANK VIEW
491→		break;
492→
493→	case 0x0c:
494→		m_cpr_leds[65] = BIT(data, 0);  // D165 - START/STOP 1 BEAT
495→		m_cpr_leds[66] = BIT(data, 1);  // D166 - START/STOP 2 BEAT
496→		m_cpr_leds[67] = BIT(data, 2);  // D167 - START/STOP 3 BEAT
497→		m_cpr_leds[68] = BIT(data, 3);  // D168 - START/STOP 4 BEAT
498→		break;
499→
500→	// Left panel LED rows
501→	case 0xc0:
502→		m_cpl_leds[1] = BIT(data, 0);  // D101 - COMPOSER: MEMORY
503→		m_cpl_leds[2] = BIT(data, 1);  // D102 - COMPOSER: MENU
504→		m_cpl_leds[3] = BIT(data, 2);  // D103 - SOUND ARRANGER: SET
505→		m_cpl_leds[4] = BIT(data, 3);  // D104 - SOUND ARRANGER: ON/OFF
506→		m_cpl_leds[5] = BIT(data, 4);  // D105 - MUSIC STYLIST
507→		m_cpl_leds[6] = BIT(data, 5);  // D106 - FADE IN
508→		m_cpl_leds[7] = BIT(data, 6);  // D107 - FADE OUT
509→		m_cpl_leds[8] = BIT(data, 7);  // D108 - DISPLAY HOLD
510→		break;
511→
512→	case 0xc1:
513→		m_cpl_leds[9] = BIT(data, 0);   // D109 - U.S. TRAD
514→		m_cpl_leds[10] = BIT(data, 1);  // D110 - COUNTRY
515→		m_cpl_leds[11] = BIT(data, 2);  // D111 - LATIN
516→		m_cpl_leds[12] = BIT(data, 3);  // D112 - MARCH & WALTZ
517→		m_cpl_leds[13] = BIT(data, 4);  // D113 - PARTY TIME
518→		m_cpl_leds[14] = BIT(data, 5);  // D114 - SHOW TIME & TRAD DANCE
519→		m_cpl_leds[15] = BIT(data, 6);  // D115 - WORLD
520→		m_cpl_leds[16] = BIT(data, 7);  // D116 - CUSTOM
521→		break;
522→
523→	case 0xc2:
524→		m_cpl_leds[17] = BIT(data, 0);  // D117 - STANDARD ROCK
525→		m_cpl_leds[18] = BIT(data, 1);  // D118 - R & ROLL & BLUES
526→		m_cpl_leds[19] = BIT(data, 2);  // D119 - POP & BALLAD
