468→		m_cpr_leds[37] = BIT(data, 4);  // D137 - CONDUCTOR: LEFT
469→		m_cpr_leds[38] = BIT(data, 5);  // D138 - CONDUCTOR: RIGHT 2
470→		m_cpr_leds[39] = BIT(data, 6);  // D139 - CONDUCTOR: RIGHT 1
471→		m_cpr_leds[40] = BIT(data, 7);  // D140 - TECHNI CHORD
472→		break;
473→
474→	case 0x08:
