199→void tlcs900_device::device_reset()
200→{
201→	m_pc.d = 0x00008000;
202→	/* system mode, iff set to 111, min mode, register bank 0 */
203→	m_sr.d = 0xf000;
204→	m_regbank = 0;
205→	m_xssp.d = 0x0100;
206→	m_halted = 0;
207→	m_check_irqs = 0;
208→	m_prefetch_clear = true;
209→}
