211→void tlcs900h_device::device_reset()
212→{
213→	m_pc.b.l = RDMEM( 0xffff00 );
214→	m_pc.b.h = RDMEM( 0xffff01 );
215→	m_pc.b.h2 = RDMEM( 0xffff02 );
216→	m_pc.b.h3 = 0;
217→	/* system mode, iff set to 111, max mode, register bank 0 */
218→	m_sr.d = 0xf800;
219→	m_regbank = 0;
220→	m_xssp.d = 0x0100;
221→	m_halted = 0;
222→	m_check_irqs = 0;
223→	m_prefetch_clear = true;
