 503→void tmp94c241_device::tffcr_w(uint8_t data)
 504→{
 505→	change_timer_flipflop( 1, (data >> 2) & 3 );
 506→	change_timer_flipflop( 3, (data >> 6) & 3 );
 507→	m_tffcr = data | 0xcc;
 508→}
