 895→	map(0x000148, 0x000149).w(FUNC(tmp94c241_device::bNcs_w<2>));
 896→	map(0x00014a, 0x00014a).rw(FUNC(tmp94c241_device::mamr_r<2>), FUNC(tmp94c241_device::mamr_w<2>));
 897→	map(0x00014b, 0x00014b).rw(FUNC(tmp94c241_device::msar_r<2>), FUNC(tmp94c241_device::msar_w<2>));
 898→	map(0x00014c, 0x00014d).w(FUNC(tmp94c241_device::bNcs_w<3>));
 899→	map(0x00014e, 0x00014e).rw(FUNC(tmp94c241_device::mamr_r<3>), FUNC(tmp94c241_device::mamr_w<3>));
 900→	map(0x00014f, 0x00014f).rw(FUNC(tmp94c241_device::msar_r<3>), FUNC(tmp94c241_device::msar_w<3>));
 901→	map(0x000150, 0x000151).w(FUNC(tmp94c241_device::bNcs_w<4>));
 902→	map(0x000152, 0x000152).rw(FUNC(tmp94c241_device::mamr_r<4>), FUNC(tmp94c241_device::mamr_w<4>));
 903→	map(0x000153, 0x000153).rw(FUNC(tmp94c241_device::msar_r<4>), FUNC(tmp94c241_device::msar_w<4>));
 904→	map(0x000154, 0x000155).w(FUNC(tmp94c241_device::bNcs_w<5>));
 905→	map(0x000156, 0x000156).rw(FUNC(tmp94c241_device::mamr_r<5>), FUNC(tmp94c241_device::mamr_w<5>));
 906→	map(0x000157, 0x000157).rw(FUNC(tmp94c241_device::msar_r<5>), FUNC(tmp94c241_device::msar_w<5>));
 907→	map(0x000400, 0x000bff).ram();
