 300→void tmp94c241_device::intnmwdt_w(offs_t offset, uint8_t data)
 301→{
 302→	if (data & 0x80)
 303→		data = (data & 0x7f) | (m_int_reg[INTNMWDT] & 0x80);
 304→	if ( data & 0x08 )
 305→		data = (data & 0xf7) | (m_int_reg[INTNMWDT] & 0x08);
 306→
 307→	m_int_reg[INTNMWDT] = data;
 308→	m_check_irqs = 1;
 309→}
