 317→void tmp94c241_device::intclr_w(uint8_t data)
 318→{
 319→	for (int i = 0; i < NUM_MASKABLE_IRQS; i++)
 320→	{
 321→		if (data == tmp94c241_irq_vector_map[i].dma_start_vector)
 322→		{
 323→			// clear interrupt request
