163→uint8_t tmp94c241_serial_device::scNbuf_r()
164→{
165→	return m_rx_buffer;
166→}
167→
168→void tmp94c241_serial_device::scNbuf_w(uint8_t data)
169→{
170→	bool was_idle = (m_tx_clock_count == 0);
171→	logerror("buf write: %02X (sioclk_state=%d, was_idle=%d)\n", data, m_sioclk_state, was_idle);
172→
173→	m_tx_shift_register = data;
174→	m_tx_clock_count = 7;  // 7 more bits to send (bits 1-7) after pre-outputting bit 0
175→
176→	// Only signal start of new transmission if we were idle.
177→	// If transmission was in progress, the slave should continue receiving
178→	// (the CPU is replacing the current byte, but byte boundary stays the same)
179→	if (was_idle)
180→	{
181→		m_tx_start_cb(1);
182→	}
183→
184→	// Pre-output first bit immediately so slave can sample it on the first rising edge
185→	logerror("pre-output bit #0: %d\n", m_tx_shift_register & 1);
186→	m_txd_cb(m_tx_shift_register & 1);
187→
188→	// Only skip the first falling edge if clock is currently HIGH AND we were idle.
189→	// If clock is HIGH: next edge = falling (skip it to avoid outputting bit 1 before receiver samples bit 0)
190→	// If clock is LOW: next edge = rising (receiver samples bit 0), then falling outputs bit 1 (no skip needed)
191→	// If we weren't idle: the slave is mid-byte, don't disrupt its counting
192→	m_tx_skip_first_falling = was_idle && (m_sioclk_state == 1);
193→	logerror("skip_first_falling = %d\n", m_tx_skip_first_falling);
194→}
