212→void tmp94c241_serial_device::scNmod_w(uint8_t data)
213→{
214→	switch((data >> 2) & 3)
215→	{
216→		case 0: logerror("I/O interface mode\n"); break;
217→		case 1: logerror("7-bit uart mode (Not implemented yet)\n"); break;
218→		case 2: logerror("8-bit uart mode (Not implemented yet)\n"); break;
219→		case 3: logerror("9-bit uart mode (Not implemented yet)\n"); break;
220→	}
221→	switch(data & 3)
222→	{
223→		case 0: logerror("clk source: TO2 trigger\n"); break;
224→		case 1: logerror("clk source: Baud rate generator (Not implemented yet)\n"); break;
225→		case 2: logerror("clk source: Internal clock at ϕ1 (Not implemented yet)\n"); break;
226→		case 3: logerror("clk source: external clock (SCLK%d) (Not implemented yet)\n", m_channel); break;
227→	}
228→	m_serial_mode = data;
229→	m_cpu->m_int_reg[(m_channel == 0) ? INTES0 : INTES1] |= 0x80;
230→	m_cpu->m_check_irqs = 1;
231→}
