560→TIMER_CALLBACK_MEMBER(kn5000_cpanel_device::timer_callback)
561→{
562→	// Timer drives the serial clock when we have data to send
563→	if (m_tx_clock_count > 0 || !m_tx_queue.empty())
564→	{
565→		// Toggle clock to shift out data
566→		m_sclk_out_cb(1);
567→		m_sclk_out_cb(0);
568→	}
