121→
122→void kn5000_cpanel_device::tx_start(int state)
123→{
124→	// Called when CPU starts transmitting a new byte - reset RX to sync byte boundaries
125→	if (state)
126→	{
127→		LOGMASKED(LOG_SERIAL, "cpanel tx_start: resetting RX counter for sync\n");
128→		m_rx_clock_count = 8;
129→		m_rx_shift_register = 0;
130→	}
131→}
132→
133→void kn5000_cpanel_device::sioclk(int state)
134→{
135→	if (m_sioclk_state == state)
136→		return;
137→
138→	m_sioclk_state = state;
139→
140→	LOGMASKED(LOG_SERIAL, "cpanel sioclk state=%d rxd=%d rx_count=%d tx_count=%d\n",
141→		state, m_rxd, m_rx_clock_count, m_tx_clock_count);
142→
143→	if (state)
144→	{
145→		// Rising edge: Sample RXD (receive bit from CPU)
146→		if (m_rx_clock_count > 0)
147→		{
148→			m_rx_shift_register >>= 1;
149→			m_rx_shift_register |= (m_rxd << 7);
150→			m_rx_clock_count--;
151→
152→			LOGMASKED(LOG_SERIAL, "cpanel RX bit: %d, shift_reg=%02X, count=%d\n",
153→				m_rxd, m_rx_shift_register, m_rx_clock_count);
154→
155→			if (m_rx_clock_count == 0)
156→			{
157→				// Full byte received
158→				m_rx_clock_count = 8;
159→				process_received_byte(m_rx_shift_register);
160→			}
161→		}
162→	}
163→	else
164→	{
165→		// Falling edge: Output TXD (transmit bit to CPU)
166→		// This prepares the bit for the CPU to sample on the next rising edge
167→		if (m_tx_skip_first_falling)
168→		{
169→			// Skip this falling edge - bit 0 was pre-output and we need to give
170→			// CPU a rising edge to sample it before we output bit 1
171→			LOGMASKED(LOG_SERIAL, "cpanel skipping first falling edge (bit 0 already on line)\n");
172→			m_tx_skip_first_falling = false;
173→		}
174→		else if (m_tx_clock_count > 0)
175→		{
176→			if (m_tx_clock_count == 8)
177→			{
178→				// First bit of a chained byte (loaded from queue) — output bit 0 without shifting
179→				LOGMASKED(LOG_SERIAL, "cpanel TX bit 0 (chained): %d, shift_reg=%02X\n",
180→					m_tx_shift_register & 1, m_tx_shift_register);
181→				m_txd_cb(m_tx_shift_register & 1);
182→				m_tx_clock_count--;
183→			}
184→			else
185→			{
186→				// Normal operation: shift out the next bit
187→				m_tx_shift_register >>= 1;
188→				LOGMASKED(LOG_SERIAL, "cpanel TX bit: %d, shift_reg=%02X, count=%d\n",
189→					m_tx_shift_register & 1, m_tx_shift_register, m_tx_clock_count);
190→				m_txd_cb(m_tx_shift_register & 1);
191→				m_tx_clock_count--;
192→			}
193→
194→			if (m_tx_clock_count == 0)
195→			{
196→				// Byte sent, check for more
197→				if (!m_tx_queue.empty())
198→				{
199→					m_tx_shift_register = m_tx_queue.front();
200→					m_tx_queue.pop();
201→					m_tx_clock_count = 8;  // Full 8 bits — don't pre-output yet
202→
203→					LOGMASKED(LOG_SERIAL, "cpanel TX next byte queued: %02X (no pre-output)\n",
204→						m_tx_shift_register);
205→
206→					// Don't pre-output: bit 7 of previous byte is still on the line
207→					// and needs to be sampled by CPU on the next rising edge.
208→					// Bit 0 of new byte will be output on the next falling edge.
209→				}
210→				else
211→				{
212→					// Return to idle
213→					LOGMASKED(LOG_SERIAL, "cpanel TX done, returning to idle\n");
214→					m_txd_cb(1);
215→				}
216→			}
217→		}
218→	}
219→}
220→
221→void kn5000_cpanel_device::send_byte(uint8_t data)
222→{
223→	LOGMASKED(LOG_SERIAL, "cpanel send_byte(%02X) tx_count=%d queue_size=%zu sioclk_state=%d\n",
224→		data, m_tx_clock_count, m_tx_queue.size(), m_sioclk_state);
225→
226→	if (m_tx_clock_count == 0 && !m_tx_skip_first_falling)
227→	{
228→		// Start sending immediately
229→		m_tx_shift_register = data;
230→		m_tx_clock_count = 7;  // 7 more bits to send after pre-outputting bit 0
231→
232→		// Pre-output first bit immediately so CPU can sample it on the first rising edge
233→		m_txd_cb(m_tx_shift_register & 1);
234→		LOGMASKED(LOG_SERIAL, "cpanel TX start: byte=%02X, pre-output bit=%d\n",
235→			data, data & 1);
236→
237→		// Only skip the first falling edge if clock is currently HIGH.
238→		// If clock is HIGH: next edge = falling (skip it)
239→		// If clock is LOW: next edge = rising (CPU samples), then falling outputs bit 1 (no skip)
240→		m_tx_skip_first_falling = (m_sioclk_state == 1);
241→		LOGMASKED(LOG_SERIAL, "cpanel TX skip_first_falling=%d\n", m_tx_skip_first_falling);
242→	}
243→	else
244→	{
245→		// Queue for later
246→		m_tx_queue.push(data);
247→		LOGMASKED(LOG_SERIAL, "cpanel TX queued: byte=%02X\n", data);
248→	}
249→}
250→
251→void kn5000_cpanel_device::process_received_byte(uint8_t data)
252→{
253→	LOGMASKED(LOG_SERIAL, "RX byte: %02X (cmd_index=%d)\n", data, m_cmd_index);
254→
255→	m_cmd_buffer[m_cmd_index++] = data;
256→
257→	if (m_cmd_index >= 2)
258→	{
259→		// Full 2-byte command received
260→		process_command();
261→		m_cmd_index = 0;
262→	}
263→}
264→
265→void kn5000_cpanel_device::process_command()
266→{
267→	uint8_t cmd = m_cmd_buffer[0];
268→	uint8_t param = m_cmd_buffer[1];
269→
270→	// Panel selection: bits 7-5 >= 4 means right panel
271→	bool is_right_panel = (cmd & 0xe0) >= 0x80;
272→
273→	LOGMASKED(LOG_COMMANDS, "Command: %02X %02X (%s panel)\n",
274→		cmd, param, is_right_panel ? "right" : "left");
275→
276→	switch (cmd)
277→	{
278→	// Initialization commands
279→	case 0x1f:  // Init sequence (left)
280→	case 0x1d:
281→	case 0x1e:
282→	case 0xdd:  // Setup mode
283→		LOGMASKED(LOG_COMMANDS, "Init command\n");
284→		send_sync_packet();
285→		m_initialized = true;
286→		break;
287→
288→	// Query commands
289→	case 0x20:  // Query left panel
290→	case 0xe0:  // Query right panel
291→		if (param == 0x00)
292→		{
293→			// Ping - respond with sync
294→			send_sync_packet();
295→		}
296→		else if (param <= 0x0a)
297→		{
298→			// Button segment query
299→			send_button_packet(param, !is_right_panel);
300→		}
301→		else if (param == 0x0b || param == 0x10)
302→		{
303→			// Status query
304→			send_sync_packet();
305→		}
306→		break;
307→
308→	case 0x25:  // Left panel data command
309→	case 0xe2:  // Right panel query
310→	case 0xe3:  // Right panel extended query
311→		send_sync_packet();
312→		break;
313→
314→	case 0x2b:  // Init button state array (left)
315→		send_all_button_states(true);
316→		break;
317→
318→	case 0xeb:  // Init button state array (right)
319→		send_all_button_states(false);
320→		break;
321→
322→	// LED control commands - right panel
323→	case 0x00:
324→	case 0x01:
325→	case 0x02:
326→	case 0x03:
327→	case 0x04:
328→	case 0x08:
329→	case 0x0a:
330→	case 0x0b:
331→	case 0x0c:
332→		process_led_command(cmd, param);
333→		send_sync_packet();
334→		break;
335→
336→	// LED control commands - left panel
337→	case 0xc0:
338→	case 0xc1:
339→	case 0xc2:
340→	case 0xc3:
341→	case 0xc4:
342→	case 0xc8:
343→		process_led_command(cmd, param);
344→		send_sync_packet();
345→		break;
346→
347→	default:
348→		// Unknown command - send sync as acknowledgment
349→		LOGMASKED(LOG_COMMANDS, "Unknown command %02X %02X\n", cmd, param);
350→		send_sync_packet();
351→		break;
352→	}
353→}
354→
355→void kn5000_cpanel_device::send_sync_packet()
356→{
357→	// Type 3 sync packet: bits 5-3 = 011 = 0x18
358→	send_byte(0x18);
359→	send_byte(0x00);
360→}
361→
362→uint8_t kn5000_cpanel_device::read_button_segment(int segment, bool is_left_panel)
363→{
364→	if (segment < 0 || segment > 10)
365→		return 0;
366→
367→	ioport_port *port = is_left_panel ? m_cpl_ports[segment] : m_cpr_ports[segment];
368→	if (port)
369→	{
370→		return port->read() & 0xff;
371→	}
372→	return 0;
373→}
374→
375→void kn5000_cpanel_device::send_button_packet(int segment, bool is_left_panel)
376→{
377→	// Button packet format:
378→	// Byte 0: [ Panel | Type | Segment ]
379→	//   - Bit 6: Panel select (0=right, 1=left)
380→	//   - Bits 5-3: Type 0 or 1 (button packet)
381→	//   - Bits 3-0 + bit 6: Segment index
382→	// Byte 1: Button state bitmap
383→
384→	uint8_t state = read_button_segment(segment, is_left_panel);
385→
386→	// For button packets, bit 6 indicates left panel
387→	uint8_t header = (segment & 0x0f);
388→	if (is_left_panel)
389→		header |= 0x40;  // Set bit 6 for left panel
390→
391→	// Type 0 for buttons (bits 5-3 = 000)
392→	send_byte(header);
393→	send_byte(state);
394→
395→	LOGMASKED(LOG_BUTTONS, "Button packet: seg=%d left=%d state=%02X\n",
396→		segment, is_left_panel, state);
397→
398→	// Track state for change detection
399→	int state_idx = is_left_panel ? (segment + 11) : segment;
400→	m_last_button_state[state_idx] = state;
401→}
402→
403→void kn5000_cpanel_device::send_all_button_states(bool is_left_panel)
404→{
405→	// Send all 11 segments for the requested panel
406→	for (int seg = 0; seg <= 10; seg++)
407→	{
408→		send_button_packet(seg, is_left_panel);
409→	}
410→}
411→
412→void kn5000_cpanel_device::process_led_command(uint8_t row, uint8_t data)
413→{
414→	LOGMASKED(LOG_LEDS, "LED command: row=%02X data=%02X\n", row, data);
415→
416→	switch (row)
417→	{
418→	// Right panel LED rows
419→	case 0x00:
420→		m_cpr_leds[1] = BIT(data, 0);  // D101 - EFFECT: SUSTAIN
421→		m_cpr_leds[2] = BIT(data, 1);  // D102 - EFFECT: DIGITAL EFFECT
422→		m_cpr_leds[3] = BIT(data, 2);  // D103 - EFFECT: DSP EFFECT
423→		m_cpr_leds[4] = BIT(data, 3);  // D104 - EFFECT: DIGITAL REVERB
424→		m_cpr_leds[5] = BIT(data, 4);  // D105 - EFFECT: ACOUSTIC ILLUSION
425→		m_cpr_leds[6] = BIT(data, 5);  // D106 - SEQUENCER: PLAY
426→		m_cpr_leds[7] = BIT(data, 6);  // D107 - SEQUENCER: EASY REC
427→		m_cpr_leds[8] = BIT(data, 7);  // D108 - SEQUENCER: MENU
428→		break;
429→
430→	case 0x01:
431→		m_cpr_leds[9] = BIT(data, 0);   // D109 - PIANO
432→		m_cpr_leds[10] = BIT(data, 1);  // D110 - GUITAR
433→		m_cpr_leds[11] = BIT(data, 2);  // D111 - STRINGS & VOCAL
434→		m_cpr_leds[12] = BIT(data, 3);  // D112 - BRASS
435→		m_cpr_leds[13] = BIT(data, 4);  // D113 - FLUTE
436→		m_cpr_leds[14] = BIT(data, 5);  // D114 - SAX & REED
437→		m_cpr_leds[15] = BIT(data, 6);  // D115 - MALLET & ORCH PERC
438→		m_cpr_leds[16] = BIT(data, 7);  // D116 - WORLD PERC
439→		break;
440→
441→	case 0x02:
442→		m_cpr_leds[17] = BIT(data, 0);  // D117 - ORGAN & ACCORDION
443→		m_cpr_leds[18] = BIT(data, 1);  // D118 - ORCHESTRAL PAD
444→		m_cpr_leds[19] = BIT(data, 2);  // D119 - SYNTH
445→		m_cpr_leds[20] = BIT(data, 3);  // D120 - BASS
446→		m_cpr_leds[21] = BIT(data, 4);  // D121 - DIGITAL DRAWBAR
447→		m_cpr_leds[22] = BIT(data, 5);  // D122 - ACCORDION REGISTER
448→		m_cpr_leds[23] = BIT(data, 6);  // D123 - GM SPECIAL
449→		m_cpr_leds[24] = BIT(data, 7);  // D124 - DRUM KITS
450→		break;
451→
452→	case 0x03:
453→		m_cpr_leds[25] = BIT(data, 0);  // D125 - PANEL MEMORY 1
454→		m_cpr_leds[26] = BIT(data, 1);  // D126 - PANEL MEMORY 2
455→		m_cpr_leds[27] = BIT(data, 2);  // D127 - PANEL MEMORY 3
456→		m_cpr_leds[28] = BIT(data, 3);  // D128 - PANEL MEMORY 4
457→		m_cpr_leds[29] = BIT(data, 4);  // D129 - PANEL MEMORY 5
458→		m_cpr_leds[30] = BIT(data, 5);  // D130 - PANEL MEMORY 6
459→		m_cpr_leds[31] = BIT(data, 6);  // D131 - PANEL MEMORY 7
460→		m_cpr_leds[32] = BIT(data, 7);  // D132 - PANEL MEMORY 8
461→		break;
462→
463→	case 0x04:
