 283→
 284→void tmp94c241_device::inte_w(offs_t offset, uint8_t data)
 285→{
 286→	if (data & 0x80)
 287→		data = (data & 0x7f) | (m_int_reg[offset] & 0x80);
 288→	if (data & 0x08)
 289→		data = (data & 0xf7) | (m_int_reg[offset] & 0x08);
 290→
 291→	m_int_reg[offset] = data;
 292→	m_check_irqs = 1;
