		m_cpr_leds[50] = BIT(data, 1);  // D150 - MENU: CONTROL
		m_cpr_leds[51] = BIT(data, 2);  // D151 - MENU: MIDI
		m_cpr_leds[52] = BIT(data, 3);  // D152 - MENU: DISK
		break;

	case 0x0a:
		m_cpr_leds[57] = BIT(data, 0);  // D157 - MEMORY A
		m_cpr_leds[58] = BIT(data, 1);  // D158 - MEMORY B
