	case 0x0b:
		m_cpr_leds[61] = BIT(data, 0);  // D161 - SYNCHRO & BREAK
		m_cpr_leds[62] = BIT(data, 1);  // D162 - R1/R2 OCTAVE MINUS
		m_cpr_leds[63] = BIT(data, 2);  // D163 - R1/R2 OCTAVE PLUS
		m_cpr_leds[64] = BIT(data, 3);  // D164 - BANK VIEW
		break;

