		m_cpr_leds[65] = BIT(data, 0);  // D165 - START/STOP 1 BEAT
		m_cpr_leds[66] = BIT(data, 1);  // D166 - START/STOP 2 BEAT
		m_cpr_leds[67] = BIT(data, 2);  // D167 - START/STOP 3 BEAT
		m_cpr_leds[68] = BIT(data, 3);  // D168 - START/STOP 4 BEAT
		break;

