		m_cpl_leds[29] = BIT(data, 4);  // D129 - MUSIC STYLE ARRANGER
		m_cpl_leds[30] = BIT(data, 5);  // D130 - AUTO PLAY CHORD
		break;

	case 0xc4:
		m_cpl_leds[33] = BIT(data, 0);  // D133 - FILL IN 1
		m_cpl_leds[34] = BIT(data, 1);  // D134 - FILL IN 2
		m_cpl_leds[35] = BIT(data, 2);  // D135 - INTRO & ENDING 1
		m_cpl_leds[36] = BIT(data, 3);  // D136 - INTRO & ENDING 2
		m_cpl_leds[37] = BIT(data, 4);  // D137 - SPLIT POINT INDICATOR (LEFT)
		m_cpl_leds[38] = BIT(data, 5);  // D138 - SPLIT POINT INDICATOR (CENTER)
		m_cpl_leds[39] = BIT(data, 6);  // D139 - SPLIT POINT INDICATOR (RIGHT)
		m_cpl_leds[40] = BIT(data, 7);  // D140 - TEMPO/PROGRAM
		break;

	case 0xc8:
		m_cpl_leds[49] = BIT(data, 0);  // D149 - OTHER PARTS/TR
		break;
	}
}

TIMER_CALLBACK_MEMBER(kn5000_cpanel_device::timer_callback)
{
	// Timer drives the serial clock when we have data to send
	if (m_tx_clock_count > 0 || !m_tx_queue.empty())
	{
		// Toggle clock to shift out data
		m_sclk_out_cb(1);
		m_sclk_out_cb(0);
	}
}
```

---

## Summary

Both files implement a High Level Emulation (HLE) of the KN5000 control panel serial protocol. Key aspects:

**Serial Protocol Features:**
- 2-byte command structure from main CPU
- Bit-banged synchronous serial using SIOCLK (clock) and RXD/TXD (data)
- Rising edge samples RXD, falling edge outputs TXD
- Pre-output of bit 0 on send_byte() with special handling of first falling edge

**Command Types:**
- Initialization commands (0x1f, 0x1d, 0x1e, 0xdd)
- Query commands (0x20, 0xe0 for button segments, LED control)
- LED control commands (rows 0x00-0x0c for right panel, 0xc0-0xc8 for left)

**Button/LED Handling:**
- 11 segments per panel (left/right)
- Segment queries return 8-bit button state bitmaps
- LED commands map directly to MAME output_finder arrays for emulator display

**Sync Protocol:**
- Type 3 sync packet (0x18 0x00) used as acknowledgment for most commands
- Button packets encode panel and segment info in header byte

